<?php
require_once __DIR__.'/includes/auth.php'; require_roles(['admin','manager']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(($_SESSION['role']??'')!=='admin'){http_response_code(403);exit('Hanya Admin boleh mengubah rekod kehadiran.');}
 verify_csrf(); $action=$_POST['action']??'save';
 if($action==='delete'){$id=(int)($_POST['id']??0);$s=$pdo->prepare('DELETE FROM attendance WHERE id=?');$s->execute([$id]);set_flash('Rekod kehadiran dipadam.');header('Location: attendance.php');exit;}
 $eid=(int)($_POST['employee_id']??0);$date=$_POST['attendance_date']??'';$status=$_POST['status']??'present';$in=($_POST['check_in']??'')?:null;$out=($_POST['check_out']??'')?:null;$ot=max(0,(float)($_POST['overtime_hours']??0));$id=(int)($_POST['id']??0);
 if(!$eid||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!in_array($status,['present','absent','leave','off_day'],true)){set_flash('Sila semak maklumat kehadiran.','danger');}
 else{if($id){$s=$pdo->prepare('UPDATE attendance SET employee_id=?,attendance_date=?,check_in=?,check_out=?,overtime_hours=?,status=? WHERE id=?');$s->execute([$eid,$date,$in,$out,$ot,$status,$id]);set_flash('Rekod kehadiran berjaya dikemas kini.');}else{$s=$pdo->prepare('INSERT INTO attendance(employee_id,attendance_date,check_in,check_out,overtime_hours,status) VALUES(?,?,?,?,?,?)');$s->execute([$eid,$date,$in,$out,$ot,$status]);set_flash('Rekod kehadiran berjaya ditambah.');}}
 header('Location: attendance.php');exit;
}
$edit=null;if(isset($_GET['edit']) && ($_SESSION['role']??'')==='admin'){$s=$pdo->prepare('SELECT * FROM attendance WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch(PDO::FETCH_ASSOC);}
$employees=$pdo->query("SELECT id,employee_code,full_name FROM employees WHERE employment_status='active' ORDER BY full_name")->fetchAll(PDO::FETCH_ASSOC);
$records=$pdo->query('SELECT a.*,e.employee_code,e.full_name FROM attendance a JOIN employees e ON e.id=a.employee_id ORDER BY a.attendance_date DESC,a.id DESC LIMIT 150')->fetchAll(PDO::FETCH_ASSOC);
require __DIR__.'/includes/layout.php';page_start('Kehadiran & OT','attendance');
?>
<div class="page-intro"><div><h2>Rekod kehadiran</h2><p>Tambah, edit atau padam rekod kehadiran dan kerja lebih masa.</p></div></div>
<div class="row g-4"><?php if(($_SESSION['role']??'')==='admin'): ?><div class="col-xl-4"><div class="panel-card"><h3 class="mb-3"><?= $edit?'Edit rekod kehadiran':'Tambah rekod kehadiran' ?></h3><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>">
<label class="form-label">Pekerja</label><select class="form-select mb-3" name="employee_id" required><option value="">Pilih pekerja</option><?php foreach($employees as $e):?><option value="<?=$e['id']?>" <?=((int)($edit['employee_id']??0)===(int)$e['id'])?'selected':''?>><?=h($e['employee_code'].' - '.$e['full_name'])?></option><?php endforeach;?></select>
<label class="form-label">Tarikh</label><input class="form-control mb-3" type="date" name="attendance_date" value="<?=h($edit['attendance_date']??date('Y-m-d'))?>" required>
<label class="form-label">Status</label><select class="form-select mb-3" name="status"><?php foreach(['present'=>'Hadir','absent'=>'Tidak hadir','leave'=>'Cuti','off_day'=>'Hari rehat'] as $v=>$label):?><option value="<?=$v?>" <?=($edit['status']??'present')===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select>
<div class="row"><div class="col-6"><label class="form-label">Masuk</label><input class="form-control mb-3" type="time" name="check_in" value="<?=h($edit['check_in']??'')?>"></div><div class="col-6"><label class="form-label">Keluar</label><input class="form-control mb-3" type="time" name="check_out" value="<?=h($edit['check_out']??'')?>"></div></div>
<label class="form-label">Jam OT</label><input class="form-control mb-3" type="number" min="0" step=".25" name="overtime_hours" value="<?=h($edit['overtime_hours']??'0')?>"><button class="btn btn-primary w-100" name="action" value="save">Simpan</button><?php if($edit):?><a class="btn btn-light w-100 mt-2" href="attendance.php">Batal edit</a><?php endif;?></form></div></div><?php endif; ?>
<div class="<?= (($_SESSION['role']??'')==='admin')?'col-xl-8':'col-12' ?>"><div class="panel-card"><h3 class="mb-3">Senarai kehadiran</h3><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Tarikh</th><th>Pekerja</th><th>Status</th><th>Masuk / Keluar</th><th>OT</th><?php if(($_SESSION['role']??'')==='admin'): ?><th>Tindakan</th><?php endif; ?></tr></thead><tbody><?php foreach($records as $r):?><tr><td><?=h($r['attendance_date'])?></td><td><b><?=h($r['full_name'])?></b><small class="d-block muted"><?=h($r['employee_code'])?></small></td><td><?=h(ucwords(str_replace('_',' ',$r['status'])))?></td><td><?=h($r['check_in']??'-')?> / <?=h($r['check_out']??'-')?></td><td><?=number_format((float)$r['overtime_hours'],2)?> jam</td><?php if(($_SESSION['role']??'')==='admin'): ?><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="attendance.php?edit=<?=(int)$r['id']?>">Edit</a> <form method="post" class="d-inline" onsubmit="return confirm('Padam rekod ini?')"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-outline-danger" name="action" value="delete">Padam</button></form></td><?php endif; ?></tr><?php endforeach;?><?php if(!$records):?><tr><td colspan="<?= (($_SESSION['role']??'')==='admin')?6:5 ?>" class="text-center muted">Tiada rekod.</td></tr><?php endif;?></tbody></table></div></div></div></div><?php page_end();?>
